export const LANGS = { en: { name: 'English', dict: en }, fr: { name: 'Français', dict: fr }, es: { name: 'Español', dict: es }, de: { name: 'Deutsch', dict: de } };
let current = 'en';
export function setLang(l) { current = LANGS[l] ? l : 'en'; document.documentElement.lang = current; }
export function getLang() { return current; }
export function t(key, vars) {
  let s = LANGS[current].dict[key] ?? en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, v);
  return s;
}
export const _dicts = { en, fr, es, de };
